INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22701, 'Matthew 20:26', 'Matthew', 20, 26, '&nbsp;خو په تاسو کښې دې داسې نۀ وى. په تاسو کښې چې څوک مشرى غواړى هغه دې ستاسو خادِم شى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22702, 'Matthew 20:27', 'Matthew', 20, 27, '&nbsp;او هر هغه څوک چې په تاسو کښې مشر کېدل غواړى هغه دې په خپله خوښه د ټولو خادِم شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22703, 'Matthew 20:28', 'Matthew', 20, 28, '&nbsp;ځکه چې اِبن آدم د دې دپاره رانۀغلو چې د هغۀ خِدمت دې وکړے شى خو د دې دپاره راغلو چې د نورو خِدمت وکړى او خپل ژوند د ډېرو دپاره فديه کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22704, 'Matthew 20:29', 'Matthew', 20, 29, '&nbsp;کله چې هغوئ د يريحو ښار نه وتل نو ډېر خلق ورپسې روان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22705, 'Matthew 20:30', 'Matthew', 20, 30, '&nbsp;د لارې په غاړه دوه ړاندۀ ناست وُو. هغوئ چې دا واورېدل چې عيسىٰ په دې لاره تېريږى نو هغوئ چغې کړې، ”اے مالِکه، د داؤد زويه، په مونږ رحم وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22706, 'Matthew 20:31', 'Matthew', 20, 31, '&nbsp;خلقو هغوئ ورټل او ورته يې ووئيل چې چپ شئ. خو هغوئ لا نورې هم چغې زياتې کړې چې، ”مالِکه، په مونږ رحم وکړه. اے د داؤد زويه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22707, 'Matthew 20:32', 'Matthew', 20, 32, '&nbsp;عيسىٰ ودرېدو او هغوئ ته يې وفرمائيل چې، ”تاسو څۀ غواړئ چې زۀ يې ستاسو دپاره وکړم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22708, 'Matthew 20:33', 'Matthew', 20, 33, '&nbsp;هغوئ ووئيل، ”مالِکه، مونږ خپل نظر غواړُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22709, 'Matthew 20:34', 'Matthew', 20, 34, '&nbsp;د عيسىٰ زړۀ پرې وسوزېدو او د هغوئ سترګو له يې لاس وروړو نو سمدستى هغوئ بينا شول او په هغۀ پسې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22710, 'Matthew 21:1', 'Matthew', 21, 1, '&nbsp;هغوئ يروشلم ته نزدې شول او کله چې دوئ د زيتُونو په غر کښې د بيتِ‌فګے کلى ته ورسېدل نو عيسىٰ دوه مريدان د دې هداياتو سره ورولېږل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22711, 'Matthew 21:2', 'Matthew', 21, 2, '&nbsp;”دې مخامخ کلى ته ورشئ نو تاسو به يوه خره تړلې ومومئ چې خپل کوچاڼے به ورسره وى. هغه پرانيزئ او ما له يې راولئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22712, 'Matthew 21:3', 'Matthew', 21, 3, '&nbsp;کۀ څوک درته څۀ وائى نو ورته ووايئ چې دا د مالِک په کار دى او هغه به يې تاسو سره سمدستى راپرېږدى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22713, 'Matthew 21:4', 'Matthew', 21, 4, '&nbsp;دا د هغې پېشګويۍ پوره کول دى چې په کښې وئيلے شوى دى چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22714, 'Matthew 21:5', 'Matthew', 21, 5, '&nbsp;”صيون لور ته ووايئ چې ګوره، ستا بادشاه درروان دے، څوک چې حليم دے، په خرۀ سور، په کوچاڼے يعنې په کوچى باندې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22715, 'Matthew 21:6', 'Matthew', 21, 6, '&nbsp;مريدان لاړل او هغه څۀ يې وکړل چې عيسىٰ ورته فرمائيلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22716, 'Matthew 21:7', 'Matthew', 21, 7, '&nbsp;خره او د هغې کوچاڼے يې راوستل، هغوئ خپلې جامې پرې واچولې او هغه پرې سور شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22717, 'Matthew 21:8', 'Matthew', 21, 8, '&nbsp;ګڼو خلقو خپلې جامې د هغۀ په لاره کښې وغوړولې او ځينې خلقو د ونو څانګې راماتې کړې او لاره يې ورته ښائسته کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22718, 'Matthew 21:9', 'Matthew', 21, 9, '&nbsp;او بيا کومه ډله چې ورنه وړاندې وروستو روانه وه هغوئ ټولو دا چغې وهلې، ”مبارک دې وى د داؤد د زوئ. مبارک دے هغه څوک چې د مالِک خُدائ په نامه راځى. په آسمان کښې دې په هغۀ مبارکى وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22719, 'Matthew 21:10', 'Matthew', 21, 10, '&nbsp;کله چې عيسىٰ يروشلم ښار ته ورننوتو نو ټول ښار کښې بلوه جوړه شوه او تپوس يې وکړو چې، ”دا څوک دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22720, 'Matthew 21:11', 'Matthew', 21, 11, '&nbsp;او ګڼې ورته جواب ورکړو چې، ”د ګليل د ناصرت نه دا عيسىٰ پېغمبر دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22721, 'Matthew 21:12', 'Matthew', 21, 12, '&nbsp;عيسىٰ بيا د خُدائ کور ته ورننوتو او هغه ټول خلق چې د خُدائ په کور کښې يې سوداګرى کوله، وشړل او د صرافانو تختې او د کونترو د خرڅوونکو کُرسۍ يې نسکورې کړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22722, 'Matthew 21:13', 'Matthew', 21, 13, '&nbsp;او ورته يې وفرمائيل چې، ”صحيفې وائى چې زما کور به د دُعا کور بللے شى، خو تاسو ترې د ډاکوانو اډه جوړه کړې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22723, 'Matthew 21:14', 'Matthew', 21, 14, '&nbsp;او د خُدائ په کور کښې ورته ړاندۀ او شل خلق راغلل او هغوئ يې روغ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22724, 'Matthew 21:15', 'Matthew', 21, 15, '&nbsp;اِمامانو او د شرعې عالمانو چې دا حېرانونکى معجزې وليدلې چې هغۀ وکړلې او د خُدائ په کور کښې چې د ماشومانو چغې واورېدې چې، ”مبارک دې وى د داؤد زوئ،“ نو دوئ خفه وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22725, 'Matthew 21:16', 'Matthew', 21, 16, '&nbsp;نو هغۀ ته يې ووئيل چې، ”دا ماشومان چې څۀ وائى، تۀ يې اورې؟“ عيسىٰ جواب ورکړو چې، ”آو، زۀ يې اورم. ولې تاسو صحيفې نۀ دى لوستلى چې، د وړو او تى رودونکو خولۀ دې ته جوړه کړه چې ستا ثنا ووائى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22726, 'Matthew 21:17', 'Matthew', 21, 17, '&nbsp;بيا د دوئ نه رُخصت شو او د ښار نه بهر بيتِ‌عنياه ته لاړو او هلته يې شپه تيره کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22727, 'Matthew 21:18', 'Matthew', 21, 18, '&nbsp;بل سحر چې عيسىٰ ښار ته راتلو نو اوږے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22728, 'Matthew 21:19', 'Matthew', 21, 19, '&nbsp;د لارې په غاړه يې د اينځر يوه ونه وليده او هغې له ورغلو خو د پاڼو نه بغېر يې په کښې هيڅ ونۀ موندل. هغۀ ونې ته وفرمائيل چې، ”تۀ دې پس د دې نه تل تر تله شنډه يې.“ او ونه په هغه ټکى اوچه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22729, 'Matthew 21:20', 'Matthew', 21, 20, '&nbsp;مريدان په دې ننداره حېران شول. هغوئ تپوس وکړو چې، ”دا لا څۀ چل دے؟ دا د اينځر ونه څنګه داسې سمدستى اوچه شوه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22730, 'Matthew 21:21', 'Matthew', 21, 21, '&nbsp;عيسىٰ ورله جواب ورکړو چې، ”زۀ تاسو ته رښتيا وايم کۀ چرې ستاسو ايمان کامِل وى او شک نۀ کوئ نو تاسو به هم هغه څۀ وکړئ کوم چې د اينځر د ونې سره وشول، خو لا د دې نه هم زيات. کۀ تاسو دې غرۀ ته ووايئ چې د دې خپل ځايه اوچت شه او سمندر کښې وغورزېږه، نو څۀ چې تاسو وايئ هغه شان به وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22731, 'Matthew 21:22', 'Matthew', 21, 22, '&nbsp;کومه دُعا چې تاسو په ايمان وغواړئ نو هغه به ټوله قبوله شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22732, 'Matthew 21:23', 'Matthew', 21, 23, '&nbsp;عيسىٰ د خُدائ کور ته ننوتو او کله چې يې تعليم ورکولو نو مشر اِمام او د قوم مشران ورله راغلل او دا سوال يې پرې وکړو چې، ”تۀ دا کارونه په کوم اختيار کوې او دا اختيار تا له چا درکړے دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22733, 'Matthew 21:24', 'Matthew', 21, 24, '&nbsp;عيسىٰ جواب ورکړو چې، ”زۀ هم ستاسو نه يو تپوس کوم، تاسو يې جواب راکړئ نو زۀ به هم تاسو ته دا وښايم چې په کوم اختيار زۀ دا کارونه کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22734, 'Matthew 21:25', 'Matthew', 21, 25, '&nbsp;د يحيىٰ بپتسمه د آسمان د لورى وه او کۀ د انسان نه؟“ په دې هغوئ د يو بل سره په بحث شول چې، ”کۀ مونږ دا ووايو چې د آسمان نه، نو هغه به راته ووائى چې بيا تاسو په هغۀ ايمان ولې رانۀ وړو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22735, 'Matthew 21:26', 'Matthew', 21, 26, '&nbsp;او کۀ دا ووايو چې د انسانانو د لورى وه، نو هسې نه چې خلق مو ونيسى ځکه چې هغوئ ټول دا منى چې يحيىٰ نبى وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22736, 'Matthew 21:27', 'Matthew', 21, 27, '&nbsp;نو هغوئ جواب ورکړو چې، ”مونږ خبر نۀ يُو.“ عيسىٰ ورته وفرمائيل چې، ”بيا به زۀ هم دا درته ونۀ وايم چې زۀ په کوم اختيار دا کارونه کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22737, 'Matthew 21:28', 'Matthew', 21, 28, '&nbsp;خو تاسو په دې حقله څۀ خيال کوئ چې د يو سړى دوه زامن وُو. هغه اول مشر له ورغلو او ورته يې ووئيل چې زويه، لاړ شه او نن د انګورو په باغ کښې کار وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22738, 'Matthew 21:29', 'Matthew', 21, 29, '&nbsp;هلک ورته جواب ورکړو چې پلاره، زۀ نۀ ځم، خو وروستو هغه پښېمانه شو او لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22739, 'Matthew 21:30', 'Matthew', 21, 30, '&nbsp;بيا پلار کشر زوئ له ورغلو او ورته يې هم هغه شان ووئيل. خو هغۀ جواب ورکړو چې زۀ به لاړ شم، خو هغه باغ ته لا نۀ ړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22740, 'Matthew 21:31', 'Matthew', 21, 31, '&nbsp;په دواړو کښې کوم يو د پلار په رضا کار وکړو؟“ هغوئ ووئيل چې، ”مشر.“ بيا عيسىٰ ورته وفرمائيل، ”زۀ تاسو ته رښتيا وايم چې محصولچيان او کنجرې به هم د خُدائ پاک په بادشاهۍ کښې ستاسو نه مخکښې داخليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22741, 'Matthew 21:32', 'Matthew', 21, 32, '&nbsp;ځکه چې کله چې يحيىٰ تاسو ته د سمې لارې د ښودلو دپاره راغلو نو تاسو پرې يقين ونۀ کړو، خو محصولچيانو او کنجرو پرې ايمان راوړو. خو سره د دې چې تاسو دا وليدل، تاسو پښېمانه نۀ شوئ او هغه مو ونۀ منلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22742, 'Matthew 21:33', 'Matthew', 21, 33, '&nbsp;يو بل مِثال واورئ، يو زميندار وو چې د انګورو باغ يې ولګولو، ګېرچاپېره يې دېوال ترې تاو کړو او په کښې يې د انګورو دپاره لنګرۍ ولګوله او د څوکيدارۍ دپاره يې په کښې يو برج جوړ کړو او بيا يې زميندارانو له په اجاره ورکړو او بل مُلک ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22743, 'Matthew 21:34', 'Matthew', 21, 34, '&nbsp;کله چې د مېوې موسم راغلو هغۀ يو نوکر اجاره دارو له ورولېږلو چې د هغوئ نه د هغۀ د پېداوار برخه وصول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22744, 'Matthew 21:35', 'Matthew', 21, 35, '&nbsp;خو هغوئ د هغۀ نوکران ونيول، يو يې ووهلو، دوېم يې مړ کړو او درېم يې سنګسار کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22745, 'Matthew 21:36', 'Matthew', 21, 36, '&nbsp;بيا هغۀ نور نوکران ورولېږل، دا ځل زيات کسان وُو او هغوئ ورسره هم هغه سلوک وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22746, 'Matthew 21:37', 'Matthew', 21, 37, '&nbsp;په آخر کښې يې خپل زوئ په دې خيال ورولېږلو چې ګنې زما د زوئ خاطر خو به وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22747, 'Matthew 21:38', 'Matthew', 21, 38, '&nbsp;خو چې زميندارو د دۀ زوئ وليدو نو يو بل ته يې ووئيل چې هم دغه وارث دے، راځئ چې مړ يې کړُو او ميراث به يې زمونږ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22748, 'Matthew 21:39', 'Matthew', 21, 39, '&nbsp;او هغه يې راونيوو د انګورو د باغ نه يې بهر وغورزولو او مړ يې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22749, 'Matthew 21:40', 'Matthew', 21, 40, '&nbsp;کله چې د انګورو د باغ مالِک راشى نو هغه به د دې زميندارو سره څۀ سلوک وکړى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
